import React, {useEffect, useMemo, useState} from "react";
import {Alert, Switch, TextField} from "@mui/material";
import SaveOutlinedIcon from "@mui/icons-material/SaveOutlined";
import ScienceOutlinedIcon from "@mui/icons-material/ScienceOutlined";
import DeleteSweepOutlinedIcon from "@mui/icons-material/DeleteSweepOutlined";
import styledCom from "styled-components";
import {toast} from "react-toastify";
import {getApiErrorMessage} from "../../api/errors";
import CoreButton from "../../ui/buttons/coreButton";
import Loader from "../../ui/loader/loader";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    Surface,
    Toolbar,
    ToolbarActions,
} from "../../ui/commonStyled/commonStyled";
import {
    defaultFirmMenuSettings,
    FirmMenuItem,
    FirmMenuSetting,
    firmMenuItemLabels,
} from "../../models/menu";
import {
    useGetMenuSettingsQuery,
    useUpdateMenuSettingsMutation,
} from "../layout/menu/menuSettingsApi";
import {useTranslation} from "../../i18n";
import {useAuth} from "../../auth/AuthContext";
import {getActiveFirmId} from "../../api/config";
import {useGetFirmQuery, useUpdateFirmMutation} from "../firms/firmsApi";
import DaDataSettingsPanel from "./DaDataSettingsPanel";
import {
    useClearTestDataMutation,
    useGetTestDataStatusQuery,
    useSeedTestDataMutation,
} from "./testDataApi";
import {
    useGetProductFileImportSettingsQuery,
    useUpdateProductFileImportSettingsMutation,
} from "../products/productsApi";

const SettingsList = styledCom.div({
    display: "grid",
    gap: "10px",
});

const SettingsStack = styledCom.div({
    display: "grid",
    gap: "16px",
});

const SettingsRow = styledCom.div({
    display: "grid",
    gridTemplateColumns: "minmax(0, 1fr) auto 120px",
    alignItems: "center",
    gap: "12px",
    minHeight: "58px",
    padding: "10px 12px",
    background: "var(--color-surface-soft)",
    border: "1px solid var(--color-border)",
    borderRadius: "12px",

    "@media (max-width: 640px)": {
        gridTemplateColumns: "1fr",
        alignItems: "stretch",
    },
});

const ImportMappingGrid = styledCom.div({
    display: "grid",
    gridTemplateColumns: "repeat(3, minmax(0, 1fr))",
    gap: "10px",

    "@media (max-width: 820px)": {
        gridTemplateColumns: "1fr",
    },
});

const ItemName = styledCom.div({
    color: "var(--color-text)",
    fontSize: "14px",
    fontWeight: 760,
});

const SectionDescription = styledCom.p({
    margin: 0,
    color: "var(--color-muted)",
    fontSize: "14px",
    lineHeight: 1.55,
});

const normalizeMenuSettings = (settings: FirmMenuSetting[] = []) => {
    const byItem = new Map(settings.map((setting) => [setting.item, setting]));

    return defaultFirmMenuSettings
        .map((defaultSetting) => ({
            ...defaultSetting,
            ...byItem.get(defaultSetting.item),
        }))
        .sort((a, b) => a.displayOrder - b.displayOrder);
};

const MenuSettingsManagement = () => {
    const {t} = useTranslation();
    const {isCompanyAdmin, isSuperAdmin, updateFirmName} = useAuth();
    const activeFirmId = Number(getActiveFirmId());
    const {data, isLoading} = useGetMenuSettingsQuery();
    const [updateMenuSettings, {isLoading: isSaving}] = useUpdateMenuSettingsMutation();
    const normalizedSettings = useMemo(() => normalizeMenuSettings(data), [data]);
    const [draftSettings, setDraftSettings] = useState<FirmMenuSetting[]>(normalizedSettings);
    const {data: firm} = useGetFirmQuery(activeFirmId, {skip: !isCompanyAdmin});
    const [updateFirm, {isLoading: isSavingFirm}] = useUpdateFirmMutation();
    const [firmName, setFirmName] = useState("");
    const [firmAddress, setFirmAddress] = useState("");
    const {
        data: testDataStatus,
        isFetching: isLoadingTestDataStatus,
        refetch: refetchTestDataStatus,
    } = useGetTestDataStatusQuery(undefined, {skip: !isSuperAdmin});
    const [seedTestData, {isLoading: isSeedingTestData}] = useSeedTestDataMutation();
    const [clearTestData, {isLoading: isClearingTestData}] = useClearTestDataMutation();
    const {data: productImportSettings, isFetching: isLoadingProductImportSettings} =
        useGetProductFileImportSettingsQuery(undefined, {skip: !isCompanyAdmin});
    const [updateProductImportSettings, {isLoading: isSavingProductImportSettings}] =
        useUpdateProductFileImportSettingsMutation();
    const [importNameColumn, setImportNameColumn] = useState("");
    const [importCountColumn, setImportCountColumn] = useState("");
    const [importColumnsText, setImportColumnsText] = useState("");
    const [importAdditionalFieldsText, setImportAdditionalFieldsText] = useState("");

    useEffect(() => {
        setDraftSettings(normalizedSettings);
    }, [normalizedSettings]);

    useEffect(() => {
        if (firm) {
            setFirmName(firm.name);
            setFirmAddress(firm.address);
        }
    }, [firm]);

    useEffect(() => {
        if (!productImportSettings) return;
        setImportNameColumn(productImportSettings.nameColumnName);
        setImportCountColumn(productImportSettings.countColumnName);
        setImportColumnsText(productImportSettings.selectedColumnNames.join("\n"));
        setImportAdditionalFieldsText(Object.entries(productImportSettings.additionalFields)
            .map(([name, value]) => `${name}=${value}`)
            .join("\n"));
    }, [productImportSettings]);

    const updateDraftSetting = (item: FirmMenuItem, updates: Partial<FirmMenuSetting>) => {
        setDraftSettings((current) =>
            current.map((setting) =>
                setting.item === item ? {...setting, ...updates} : setting,
            ),
        );
    };

    const saveSettings = async () => {
        try {
            await updateMenuSettings(
                [...draftSettings].sort((a, b) => a.displayOrder - b.displayOrder),
            ).unwrap();
            toast.success(t("Menu settings saved"));
        } catch (error) {
            toast.error(getApiErrorMessage(error, t("Menu settings were not saved")));
        }
    };

    const saveFirm = async () => {
        try {
            const updatedFirm = await updateFirm({
                id: activeFirmId,
                body: {name: firmName, address: firmAddress},
            }).unwrap();
            updateFirmName(updatedFirm.name);
            toast.success("Компания обновлена");
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось обновить компанию"));
        }
    };

    const seedDemoData = async () => {
        try {
            const result = await seedTestData().unwrap();
            toast.success(
                result.addedRecordCount > 0
                    ? `Тестовые данные добавлены (${result.addedRecordCount} записей)`
                    : "Тестовые данные уже добавлены",
            );
            await refetchTestDataStatus();
            window.setTimeout(() => window.location.reload(), 450);
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось добавить тестовые данные"));
        }
    };

    const removeDemoData = async () => {
        if (!window.confirm(
            "Удалить все данные, созданные тестовым сидером? Пользовательские данные останутся в базе.",
        )) {
            return;
        }

        try {
            const result = await clearTestData().unwrap();
            const preservedSuffix = result.preservedRecordCount > 0
                ? ` Сохранено связанных пользовательских записей: ${result.preservedRecordCount}.`
                : "";
            toast.success(`Тестовые данные удалены.${preservedSuffix}`);
            await refetchTestDataStatus();
            window.setTimeout(() => window.location.reload(), 450);
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось удалить тестовые данные"));
        }
    };

    const saveProductImportSettings = async () => {
        const selectedColumnNames = importColumnsText
            .split(/\r?\n/)
            .map((value) => value.trim())
            .filter(Boolean);
        const additionalFields: Record<string, string> = {};
        const additionalNames = new Set<string>();
        for (const line of importAdditionalFieldsText.split(/\r?\n/).map((value) => value.trim()).filter(Boolean)) {
            const separator = line.indexOf("=");
            const name = separator < 0 ? "" : line.slice(0, separator).trim();
            const value = separator < 0 ? "" : line.slice(separator + 1).trim();
            const normalizedName = name.toLocaleLowerCase();
            if (!name || !value) {
                toast.error("Дополнительные поля указываются в формате Название=Значение");
                return;
            }
            if (additionalNames.has(normalizedName)) {
                toast.error(`Поле «${name}» указано несколько раз`);
                return;
            }
            additionalNames.add(normalizedName);
            additionalFields[name] = value;
        }

        try {
            await updateProductImportSettings({
                nameColumnName: importNameColumn.trim(),
                priceColumnName: "",
                countColumnName: importCountColumn.trim(),
                selectedColumnNames,
                additionalFields,
            }).unwrap();
            toast.success("Настройки импорта товаров сохранены");
        } catch (error) {
            toast.error(getApiErrorMessage(error, "Не удалось сохранить настройки импорта"));
        }
    };

    if (isLoading) {
        return <Loader/>;
    }

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t("Settings")}</PageTitle>
                    <PageSubtitle>
                        Подключения, импорт из Excel и навигация компании.
                    </PageSubtitle>
                </PageTitleGroup>
            </PageHeader>
            <SettingsStack>
            <DaDataSettingsPanel key={activeFirmId}/>
            {isSuperAdmin && (
                <Surface>
                    <Toolbar>
                        <ItemName>Реквизиты компании</ItemName>
                        <ToolbarActions>
                            <CoreButton
                                muiType="success"
                                text={isSavingFirm ? "Сохранение..." : "Сохранить компанию"}
                                leftIcon={<SaveOutlinedIcon/>}
                                onClick={saveFirm}
                                disabled={isSavingFirm || !firmName.trim()}
                            />
                        </ToolbarActions>
                    </Toolbar>
                    <SettingsList>
                        <TextField
                            label="Название компании"
                            value={firmName}
                            onChange={(event) => setFirmName(event.target.value)}
                        />
                        <TextField
                            label="Адрес"
                            value={firmAddress}
                            onChange={(event) => setFirmAddress(event.target.value)}
                        />
                    </SettingsList>
                </Surface>
            )}
            {isCompanyAdmin && (
                <Surface>
                    <Toolbar>
                        <ItemName>Тестовые данные</ItemName>
                        <ToolbarActions>
                            <CoreButton
                                muiType="success"
                                text={isSeedingTestData ? "Наполнение..." : "Наполнить тестовыми данными"}
                                leftIcon={<ScienceOutlinedIcon/>}
                                onClick={seedDemoData}
                                disabled={
                                    isSeedingTestData ||
                                    isClearingTestData ||
                                    isLoadingTestDataStatus ||
                                    Boolean(testDataStatus?.hasTestData)
                                }
                            />
                            <CoreButton
                                muiType="error"
                                text={isClearingTestData ? "Удаление..." : "Убрать тестовые данные"}
                                leftIcon={<DeleteSweepOutlinedIcon/>}
                                onClick={removeDemoData}
                                disabled={
                                    isSeedingTestData ||
                                    isClearingTestData ||
                                    isLoadingTestDataStatus ||
                                    !testDataStatus?.hasTestData
                                }
                            />
                        </ToolbarActions>
                    </Toolbar>
                    <SettingsList>
                        <SectionDescription>
                            Добавьте демонстрационные компании, пользователей, каталог, клиентов, заказы и логистику.
                            При очистке удалятся только добавленные тестовые записи. Ваши собственные данные сохранятся.
                        </SectionDescription>
                        <Alert severity={testDataStatus?.hasTestData ? "info" : "success"}>
                            {isLoadingTestDataStatus
                                ? "Проверяем состояние тестовых данных..."
                                : testDataStatus?.legacySeedDetected
                                    ? "Найдены ранее добавленные демонстрационные данные. Их можно убрать этой кнопкой."
                                    : testDataStatus?.hasTestData
                                        ? `Тестовые данные добавлены. Отслеживается записей: ${testDataStatus.trackedRecordCount}.`
                                        : "Тестовых данных в базе нет."}
                        </Alert>
                    </SettingsList>
                </Surface>
            )}
            {isCompanyAdmin && (
                <Surface>
                    <Toolbar>
                        <div>
                            <ItemName>Импорт товаров из Excel</ItemName>
                            <SectionDescription>
                                Укажите заголовки колонок из шаблона поставщика. При загрузке файла они будут выбраны автоматически. Цены заполняются в карточке или из файла для прихода. В ePass количество упаковки сохраняется как характеристика, складской остаток не переносится.
                            </SectionDescription>
                        </div>
                        <ToolbarActions>
                            <CoreButton
                                muiType="success"
                                text={isSavingProductImportSettings ? "Сохранение..." : "Сохранить настройки импорта"}
                                leftIcon={<SaveOutlinedIcon/>}
                                onClick={saveProductImportSettings}
                                disabled={isSavingProductImportSettings || isLoadingProductImportSettings}
                            />
                        </ToolbarActions>
                    </Toolbar>
                    <SettingsList>
                        <ImportMappingGrid>
                            <TextField fullWidth size="small" label="Колонка названия" placeholder="Например: Название товара" value={importNameColumn} onChange={(event) => setImportNameColumn(event.target.value)}/>
                            <TextField fullWidth size="small" label="Колонка остатка" placeholder="Например: Остаток" value={importCountColumn} onChange={(event) => setImportCountColumn(event.target.value)}/>
                        </ImportMappingGrid>
                        <TextField
                            multiline
                            minRows={3}
                            label="Колонки, которые нужно добавлять в поля товара"
                            placeholder={"Бренд\nСтрана производства\nАртикул поставщика"}
                            helperText="По одному точному заголовку колонки на строку."
                            value={importColumnsText}
                            onChange={(event) => setImportColumnsText(event.target.value)}
                        />
                        <TextField
                            multiline
                            minRows={2}
                            label="Постоянные дополнительные поля"
                            placeholder={"Поставщик=Основной поставщик\nКанал=Excel"}
                            helperText="Этих колонок может не быть в файле: поле будет добавлено каждому товару. Формат — Название=Значение."
                            value={importAdditionalFieldsText}
                            onChange={(event) => setImportAdditionalFieldsText(event.target.value)}
                        />
                    </SettingsList>
                </Surface>
            )}
            <Surface>
                <Toolbar>
                    <ItemName>{t("Firm menu")}</ItemName>
                    <ToolbarActions>
                        <CoreButton
                            muiType="success"
                            text={isSaving ? t("Saving...") : t("Save")}
                            leftIcon={<SaveOutlinedIcon/>}
                            onClick={saveSettings}
                            disabled={isSaving}
                        />
                    </ToolbarActions>
                </Toolbar>
                <SettingsList>
                    {draftSettings.map((setting) => (
                        <SettingsRow key={setting.item}>
                            <ItemName>{t(firmMenuItemLabels[setting.item])}</ItemName>
                            <Switch
                                checked={setting.isVisible}
                                inputProps={{"aria-label": t(firmMenuItemLabels[setting.item])}}
                                onChange={(event) =>
                                    updateDraftSetting(setting.item, {isVisible: event.target.checked})
                                }
                            />
                            <TextField
                                size="small"
                                type="number"
                                label={t("Order")}
                                value={setting.displayOrder}
                                onChange={(event) =>
                                    updateDraftSetting(setting.item, {
                                        displayOrder: Number(event.target.value),
                                    })
                                }
                            />
                        </SettingsRow>
                    ))}
                </SettingsList>
            </Surface>
            </SettingsStack>
        </MainDiv>
    );
};

export default MenuSettingsManagement;
