import React, {useState} from 'react';
import {Alert, Button, Checkbox, FormControlLabel, Stack, TextField, Typography} from '@mui/material';
import SaveOutlinedIcon from '@mui/icons-material/SaveOutlined';
import {getApiErrorMessage} from '../../api/errors';
import {useAuth} from '../../auth/AuthContext';
import {Surface, Toolbar, ToolbarActions} from '../../ui/commonStyled/commonStyled';
import CoreButton from '../../ui/buttons/coreButton';
import {useDaDataSettingsQuery, useResetDaDataSettingsMutation, useUpdateDaDataSettingsMutation} from '../counterparties/counterpartiesApi';

function SettingsForm() {
    const {data, isFetching, isError, refetch} = useDaDataSettingsQuery();
    const [update, updateState] = useUpdateDaDataSettingsMutation();
    const [reset, resetState] = useResetDaDataSettingsMutation();
    const [apiKey, setApiKey] = useState('');
    const [secretKey, setSecretKey] = useState('');
    const [clearSecretKey, setClearSecretKey] = useState(false);
    const [message, setMessage] = useState('');
    const [error, setError] = useState('');
    const busy = updateState.isLoading || resetState.isLoading;

    function clearDraft() {setApiKey(''); setSecretKey(''); setClearSecretKey(false);}

    async function save() {
        setError(''); setMessage('');
        try {
            await update({apiKey: apiKey.trim() || undefined, secretKey: secretKey.trim() || undefined, clearSecretKey}).unwrap();
            clearDraft();
            setMessage('Настройки DaData сохранены. Новые запросы используют сохранённые ключи.');
        } catch (failure) {setError(getApiErrorMessage(failure, 'Не удалось сохранить настройки DaData.'));}
        finally {updateState.reset();}
    }

    async function resetKeys() {
        setError(''); setMessage('');
        try {
            await reset().unwrap();
            clearDraft();
            setMessage('Ключи компании удалены. Используются общие настройки DaData сервера, если они заданы.');
        } catch (failure) {setError(getApiErrorMessage(failure, 'Не удалось сбросить настройки DaData.'));}
    }

    return <Surface>
        <Toolbar>
            <div>
                <Typography component="h2" fontSize={14} fontWeight={760}>DaData — проверка контрагентов</Typography>
                <Typography variant="body2" color="text.secondary">Ключи действуют для выбранной компании. API-ключ нужен для поиска организаций, секретный — для стандартизации и личного кабинета DaData.</Typography>
            </div>
            <ToolbarActions>
                <CoreButton type="button" muiType="success" leftIcon={<SaveOutlinedIcon/>}
                    text={updateState.isLoading ? 'Сохранение...' : 'Сохранить ключи DaData'} onClick={() => void save()}
                    disabled={busy || isFetching || !data || (!apiKey.trim() && !secretKey.trim() && !clearSecretKey) || (!data.hasApiKey && !apiKey.trim())}/>
            </ToolbarActions>
        </Toolbar>
        <Stack spacing={2}>
            {isFetching && <Typography role="status" variant="body2">Загрузка настроек DaData...</Typography>}
            {isError && <Alert severity="error" action={<Button onClick={() => void refetch()}>Повторить</Button>}>Не удалось загрузить настройки DaData.</Alert>}
            {data && <Alert severity={data.hasApiKey ? 'success' : 'info'}>
                {data.hasApiKey ? `API-ключ задан. ${data.hasSecretKey ? 'Секретный ключ задан.' : 'Секретный ключ не задан.'}` : 'API-ключ ещё не задан.'}
                {data.usesServerDefaults && data.hasApiKey ? ' Используются общие настройки сервера.' : ''}
            </Alert>}
            <Stack direction={{xs: 'column', md: 'row'}} spacing={2}>
                <TextField fullWidth type="password" label="API-ключ DaData" autoComplete="new-password" value={apiKey}
                    disabled={busy || isFetching || !data} inputProps={{maxLength: 256}}
                    helperText={data?.hasApiKey ? 'Оставьте пустым, чтобы сохранить текущий API-ключ.' : 'Вставьте API-ключ из личного кабинета DaData.'}
                    onChange={event => {setApiKey(event.target.value); setMessage('');}}/>
                <TextField fullWidth type="password" label="Секретный ключ DaData" autoComplete="new-password" value={secretKey}
                    disabled={busy || isFetching || !data || clearSecretKey} inputProps={{maxLength: 256}}
                    helperText={data?.hasSecretKey ? 'Оставьте пустым, чтобы сохранить текущий секретный ключ.' : 'Необязательно для поиска организаций.'}
                    onChange={event => {setSecretKey(event.target.value); setMessage('');}}/>
            </Stack>
            {data?.hasSecretKey && <FormControlLabel label="Удалить секретный ключ" control={<Checkbox checked={clearSecretKey} disabled={busy || isFetching}
                onChange={event => {setClearSecretKey(event.target.checked); setSecretKey(''); setMessage('');}}/>}/>}
            <Typography variant="caption" color="text.secondary">Ключи хранятся на сервере в зашифрованном виде. Сохранённые значения не отображаются.</Typography>
            {data && !data.usesServerDefaults && <Button color="error" disabled={busy || isFetching} onClick={() => void resetKeys()} sx={{alignSelf: 'flex-start'}}>Сбросить ключи компании</Button>}
            {message && <Alert severity="success">{message}</Alert>}
            {error && <Alert severity="error">{error}</Alert>}
        </Stack>
    </Surface>;
}

export default function DaDataSettingsPanel() {
    const {isCompanyAdmin} = useAuth();
    return isCompanyAdmin ? <SettingsForm/> : null;
}
